_LEGAL = [('g0c04e87f', 'ООО «Современные управленческие решения»'), ('gb38c3c8d', 'АО «Дарбшир»'), ('g51c9c9a4', 'ООО «Красная руда»')]

_RETRACT = [('cb7eb501d', 'eco.sum', 'Не разглашается (возможная сумма сделки — от 10 млрд до 13 млрд руб., согласно открытым источникам)')]


def _get(obj, field):
    for p in field.split('.'):
        obj = obj.get(p) if isinstance(obj, dict) else None
    return obj


def _set(obj, field, value):
    parts = field.split('.')
    for p in parts[:-1]:
        obj = obj.setdefault(p, {})
    obj[parts[-1]] = value


def apply(data):
    n = 0
    deals = {d['id']: d for d in data['deals']}
    for cid, field, old, new, quote, url in _SET:
        card = deals[cid]
        if _get(card, field) == new:
            continue
        assert _get(card, field) == old, (cid, field, _get(card, field))
        _set(card, field, new)
        if quote:
            fact_edit_guard.log(card, field, new, quote, url, BY)
        n += 1
    for cid, field, value in _RETRACT:
        lst = deals[cid].setdefault('retracted', {}).setdefault(field, [])
        if value not in lst:
            lst.append(value)
            n += 1
    for comp, short in _LEGAL:
        c = data['companies'][comp]
        if c.get('legal_short') != short:
            assert not c.get('legal_short'), (comp, c.get('legal_short'))
            c['legal_short'] = short
            n += 1
    return n


if __name__ == '__main__':
    data = json.load(open(DATA, encoding='utf-8'))
    n = apply(data)
    print('Изменений: %d' % n if n else 'Уже применено.')
    if '--write' in sys.argv and n:
        data = json.load(open(DATA, encoding='utf-8'))      # перечитать прямо перед записью
        apply(data)
        json.dump(data, open(DATA, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
        print('Записано.')
    elif '--write' not in sys.argv:
        print('Сухой прогон. Запись — с ключом --write.')
